CREATE OR REPLACE PROCEDURE eks_calculation.srmara_eks_item_constructskfromea_ins()
BEGIN
INSERT INTO eks_calculation.stmara_eks_item_1 (itemid, bitflag, employeeid, cr_locationid, itemgrouptypeid, itemno, shortdesc_int, shortdesc_nat, description_int, description_nat, in_use, zlegacymandt, zlegacymatnr, zlegacymatkl, zlegacysatnr, zactive, zmtart, zmatkl, zbismt, zmeins, zzeinr, ztragr, zbwscl, zvabme, zbegru, zattyp, zmstae, zmstde, ztaklv, zinhme, zinhal, zvpreh, zisvalidbitflag, zisin_use, zisfood, ziscurrentcontract, znegotiatingcountry, zarticletype, zitem_ba, zsource, constructed, constructedfrom, zskcasesize, targetsystem, targetclient)
(SELECT CAST(ROUND(CAST(itemid AS BIGNUMERIC),0) AS INT64), bitflag, employeeid, cr_locationid, itemgrouptypeid, CAST(ROUND(CAST(itemno AS BIGNUMERIC),0) AS INT64), shortdesc_int, shortdesc_nat, description_int, description_nat, in_use, zlegacymandt, zlegacymatnr, zlegacymatkl, SUBSTR(CAST(zlegacysatnr AS STRING), 1, 50) AS zlegacysatnr, zactive, zmtart, zmatkl, SUBSTR(CAST(zbismt AS STRING), 1, 18) AS zbismt, zmeins, zzeinr, ztragr, zbwscl, zvabme, zbegru, zattyp, zmstae, zmstde, ztaklv, SUBSTR(CAST(zinhme AS STRING), 1, 3) AS zinhme, zinhal, CAST(zvpreh AS INTEGER) AS zvpreh, zisvalidbitflag, zisin_use, zisfood, ziscurrentcontract, znegotiatingcountry, zarticletype, zitem_ba, zsource, constructed, SUBSTR(CAST(constructedfrom AS STRING), 1, 255) AS constructedfrom, CAST(zskcasesize AS INTEGER) AS zskcasesize, targetsystem, targetclient
    FROM eks_calculation.srmara_eks_item_constructskfromea_inssel_1);
END;

